#include "ml_structures.h"
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
enum{ROWS=200000,FEATURES=32,BATCH=256,EMB_ROWS=100000,DIMS=64,GATHERS=200000};static double e(struct timespec a,struct timespec b){return(double)(b.tv_sec-a.tv_sec)+(double)(b.tv_nsec-a.tv_nsec)/1e9;}
int main(void){MlDataset*d=ml_dataset_create(ROWS,FEATURES);if(!d)return 1;float row[FEATURES];for(size_t f=0;f<FEATURES;++f)row[f]=(float)f;for(size_t r=0;r<ROWS;++r)if(!ml_dataset_set_row(d,r,row,(int)(r%10)))return 2;BatchPlan*p=batch_plan_create(ROWS,BATCH,42);float*out=malloc((size_t)BATCH*FEATURES*sizeof(float));int*labels=malloc((size_t)BATCH*sizeof(int));if(!p||!out||!labels)return 3;struct timespec a,b,c;timespec_get(&a,TIME_UTC);for(;;){const size_t*idx;size_t n;bool has;if(!batch_plan_next(p,&idx,&n,&has))return 4;if(!has)break;if(!ml_dataset_gather(d,idx,n,out,labels))return 5;}timespec_get(&b,TIME_UTC);EmbeddingTable*emb=embedding_create(EMB_ROWS,DIMS);float erow[DIMS];for(size_t j=0;j<DIMS;++j)erow[j]=(float)j;for(size_t r=0;r<EMB_ROWS;++r)if(!embedding_set_row(emb,r,erow))return 6;size_t*idx=malloc((size_t)BATCH*sizeof(size_t));float*eg=malloc((size_t)BATCH*DIMS*sizeof(float));if(!emb||!idx||!eg)return 7;size_t done=0;while(done<GATHERS){size_t n=(GATHERS-done)<BATCH?(GATHERS-done):BATCH;for(size_t i=0;i<n;++i)idx[i]=(done+i)%EMB_ROWS;if(!embedding_gather(emb,idx,n,eg))return 8;done+=n;}timespec_get(&c,TIME_UTC);printf("dataset_gather_seconds=%.6f embedding_gather_seconds=%.6f\n",e(a,b),e(b,c));free(eg);free(idx);embedding_free(emb);free(labels);free(out);batch_plan_free(p);ml_dataset_free(d);return 0;}
